import { locales, services, industries, experts, routePages } from './content.js';

export const slugs = {
  fr: { home: '', about: 'a-propos', services: 'services-et-secteurs', projects: 'projets', insights: 'insights', actuality: 'actualites', sustainability: 'durabilite', experts: 'experts', careers: 'carrieres', contact: 'contact', newsletter: 'infolettre', search: 'recherche', privacy: 'confidentialite', cookies: 'temoins', terms: 'conditions', legal: 'mentions-legales', accessibility: 'accessibilite', consent: 'gestion-consentement', recruitment: 'confidentialite-candidatures' },
  en: { home: '', about: 'about', services: 'services-industries', projects: 'projects', insights: 'insights', actuality: 'actuality', sustainability: 'sustainability', experts: 'experts', careers: 'careers', contact: 'contact', newsletter: 'newsletter', search: 'search', privacy: 'privacy', cookies: 'cookies', terms: 'terms', legal: 'legal-notices', accessibility: 'accessibility', consent: 'consent-management', recruitment: 'recruitment-privacy' },
};

const e = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const href = (lang, key) => `/${lang}/${slugs[lang][key] ? `${slugs[lang][key]}/` : ''}`;
const serviceHref = (lang, slug) => `${href(lang, 'services')}${lang === 'fr' ? 'services/' : 'services/'}${slug}/`;
const industryHref = (lang, slug) => `${href(lang, 'services')}${lang === 'fr' ? 'secteurs/' : 'industries/'}${slug}/`;
const itemName = (item, lang) => lang === 'fr' ? item[2] : item[1];
const getTitle = (key, lang) => routePages[key]?.[lang]?.[0] || locales[lang].label;
const getDescription = (key, lang) => routePages[key]?.[lang]?.[1] || '';

export function renderSite({ lang, route, origin = '', csrf = '', recaptchaSiteKey = '', recaptchaTestMode = false, query = '', cmsItems = [] }) {
  const t = locales[lang];
  const basePath = `/${lang}/`;
  const title = route.title || getTitle(route.key, lang);
  const description = seoDescription(route.description || getDescription(route.key, lang), lang);
  const body = renderBody({ lang, route, csrf, recaptchaSiteKey, recaptchaTestMode, query, title, cmsItems });
  if (body === null) return null;
  const routePath = route.path || href(lang, route.key);
  const canonical = origin && !route.errorStatus ? `<link rel="canonical" href="${e(origin + routePath)}">` : '';
  const alternateLang = lang === 'fr' ? 'en' : 'fr';
  const altPath = route.altPath || href(alternateLang, route.altKey || route.key);
  const alternates = origin && !route.errorStatus ? `<link rel="alternate" hreflang="fr" href="${e(origin + (lang === 'fr' ? routePath : route.altPath || href('fr', route.altKey || route.key)))}"><link rel="alternate" hreflang="en" href="${e(origin + (lang === 'en' ? routePath : route.altPath || href('en', route.altKey || route.key)))}"><link rel="alternate" hreflang="x-default" href="${e(origin + href('fr', 'home'))}">` : '';
  const logo = '/assets/brand/apah-logo.svg';
  const nav = t.nav.map(([key, label]) => key === 'services' ? renderServicesMenu(lang, label, route) : key === 'contact' ? `<a class="button button-small button-dark nav-contact" href="${href(lang, key)}"${route.key === key ? ' aria-current="page"' : ''}>${e(label)}</a>` : `<a href="${href(lang, key)}"${route.key === key ? ' aria-current="page"' : ''}>${e(label)}</a>`).join('');
  const footerGroups = lang === 'fr' ? [
    ['Explorer', ['about', 'services', 'projects', 'actuality']], ['Domaines', ['insights', 'sustainability', 'experts', 'careers']], ['Informations', ['contact', 'terms', 'privacy', 'cookies', 'consent', 'accessibility', 'legal']],
  ] : [
    ['Explore', ['about', 'services', 'projects', 'actuality']], ['Expertise', ['insights', 'sustainability', 'experts', 'careers']], ['Information', ['contact', 'terms', 'privacy', 'cookies', 'consent', 'accessibility', 'legal']],
  ];
  const footer = footerGroups.map(([heading, keys]) => `<div><h2>${e(heading)}</h2>${keys.map(key => `<a href="${href(lang, key)}">${e(getTitle(key, lang))}</a>`).join('')}</div>`).join('');
  const header = `<header class="site-header" data-header><a class="brand" href="${basePath}" aria-label="Africa Power Advisory Holdings, ${e(t.home.toLowerCase())}"><img src="${logo}" data-logo-light="/assets/brand/apah-logo-light.svg" data-logo-full="${logo}" width="190" height="56" alt="Africa Power Advisory Holdings"></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="primary-navigation" aria-label="${e(t.menu)}"><span></span><span></span><span></span></button><nav class="primary-nav" id="primary-navigation" aria-label="${lang === 'fr' ? 'Navigation principale' : 'Primary navigation'}">${nav}<div class="nav-tools"><a class="button button-small button-outline" href="${href(lang, 'newsletter')}">${e(t.newsletter)}</a><button class="theme-toggle" type="button" data-theme-toggle aria-pressed="false">${e(t.dark)}</button><span class="language-switch" aria-label="${lang === 'fr' ? 'Langue' : 'Language'}"><a lang="fr" aria-label="${lang === 'fr' ? 'Page en français' : 'Switch to French'}"${lang === 'fr' ? ' aria-current="true"' : ''} href="${e(lang === 'fr' ? routePath : route.altPath || href('fr', route.altKey || route.key))}">FR</a><span aria-hidden="true">|</span><a lang="en" aria-label="${lang === 'en' ? 'Page en anglais' : 'Switch to English'}"${lang === 'en' ? ' aria-current="true"' : ''} href="${e(lang === 'en' ? routePath : route.altPath || href('en', route.altKey || route.key))}">EN</a></span><form class="header-search" action="${href(lang, 'search')}" method="get"><button class="search-toggle" type="button" aria-expanded="false" aria-controls="header-search-form" aria-label="${e(t.search)}">⌕</button><div class="header-search-panel" id="header-search-form" hidden><label class="visually-hidden" for="header-search-input">${e(t.searchLabel)}</label><input id="header-search-input" name="q" type="search" required value="${e(query)}" placeholder="${e(t.searchPlaceholder)}"><button type="submit">${e(t.search)}</button></div></form></div></nav></header>`;
  const offices = lang === 'fr'
    ? '<span class="office-label">Bureaux</span><br>Kinshasa, République démocratique du Congo<br>Makeni 55, Kafue Road<br>Lusaka, Zambie'
    : '<span class="office-label">Offices</span><br>Kinshasa, Democratic Republic of the Congo<br>Makeni 55, Kafue Road<br>Lusaka, Zambia';
  const footerMarkup = `<footer class="site-footer"><div class="footer-main"><div><a class="brand brand-light" href="${basePath}" aria-label="Africa Power Advisory Holdings, ${e(t.home.toLowerCase())}"><img src="/assets/brand/apah-logo-light.svg" width="190" height="56" alt="Africa Power Advisory Holdings"></a><p class="footer-description">${e(t.footer)}</p><address class="footer-address">Africa Power Advisory Holding · SARL<br>${offices}</address></div><div class="footer-links">${footer}</div></div><div class="footer-bottom"><span>© <span data-year></span> Africa Power Advisory Holding</span><a href="${href(lang, 'newsletter')}">${e(t.newsletterCta)}</a><button class="theme-toggle theme-toggle-footer" type="button" data-theme-toggle aria-pressed="false">${e(t.dark)}</button><span class="language-switch"><a lang="fr" aria-label="${lang === 'fr' ? 'Page en français' : 'Switch to French'}"${lang === 'fr' ? ' aria-current="true"' : ''} href="${e(lang === 'fr' ? routePath : route.altPath || href('fr', route.altKey || route.key))}">Français</a><span aria-hidden="true">|</span><a lang="en" aria-label="${lang === 'en' ? 'Page en anglais' : 'Switch to English'}"${lang === 'en' ? ' aria-current="true"' : ''} href="${e(lang === 'en' ? routePath : route.altPath || href('en', route.altKey || route.key))}">English</a></span></div></footer>`;
  const suggestion = route.suggestedLanguage ? `<aside class=\"language-suggestion\" role=\"status\">${lang === 'fr' ? 'Préférez-vous lire en anglais ?' : 'Would you prefer French?'} <a lang=\"en\" href=\"/en/\">${lang === 'fr' ? 'English' : 'Switch to English'}</a></aside>` : '';
  const organization = { '@context': 'https://schema.org', '@type': 'Organization', name: 'Africa Power Advisory Holdings', legalName: 'Africa Power Advisory Holding', address: { '@type': 'PostalAddress', addressLocality: 'Kinshasa', addressCountry: 'CD' } };
  const schemaData = route.key === 'home' && !route.errorStatus ? [organization] : [];
  if (route.key === 'actuality-detail' && route.author && route.publishedAt && origin && !route.errorStatus) schemaData.push({ '@context': 'https://schema.org', '@type': 'NewsArticle', headline: title, description: route.description, datePublished: route.publishedAt, ...(route.updatedAt ? { dateModified: route.updatedAt } : {}), author: { '@type': 'Person', name: route.author }, publisher: organization, mainEntityOfPage: origin + routePath });
  if (['service-detail','industry-detail','expert-detail','actuality-detail','career-detail','project-detail','insight-detail'].includes(route.key) && origin && !route.errorStatus) {
    const parentKey = { 'service-detail':'services','industry-detail':'services','expert-detail':'experts','actuality-detail':'actuality','career-detail':'careers','project-detail':'projects','insight-detail':'insights' }[route.key];
    schemaData.push({ '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: [{ '@type':'ListItem', position:1, name:t.home, item:origin + href(lang,'home') }, { '@type':'ListItem', position:2, name:getTitle(parentKey,lang), item:origin + href(lang,parentKey) }, { '@type':'ListItem', position:3, name:title, item:origin + routePath }] });
  }
  const schema = schemaData.map(value => `<script type="application/ld+json">${JSON.stringify(value).replace(/</g, '\\u003c')}</script>`).join('');
  return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#102b55"><meta name="description" content="${e(description)}"><meta name="robots" content="${route.errorStatus || !origin ? 'noindex,follow' : 'index,follow'}"><meta property="og:title" content="${e(title)} | Africa Power Advisory Holdings"><meta property="og:description" content="${e(description)}"><meta property="og:type" content="website"><meta property="og:locale" content="${lang === 'fr' ? 'fr_CD' : 'en_CD'}">${canonical}${alternates}<link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="manifest" href="/site.webmanifest"><link rel="stylesheet" href="/styles.css"><script src="/script.js" defer></script><title>${e(title)} | Africa Power Advisory Holdings</title>${schema}</head><body><a class="skip-link" href="#main">${lang === 'fr' ? 'Aller au contenu' : 'Skip to content'}</a>${suggestion}${header}<main id="main">${body}</main>${footerMarkup}<section class="cookie-banner" data-cookie-banner hidden aria-label="${lang === 'fr' ? 'Préférences relatives aux cookies' : 'Cookie preferences'}"><p>${lang === 'fr' ? 'Ce site utilise uniquement le stockage fonctionnel nécessaire par défaut. Les services facultatifs restent désactivés jusqu’à votre accord.' : 'This site uses only necessary functional storage by default. Optional services remain off until you consent.'}</p><a href="${href(lang, 'consent')}">${lang === 'fr' ? 'Gérer les préférences' : 'Manage preferences'}</a><button type="button" data-cookie-accept>${lang === 'fr' ? 'Compris' : 'Understood'}</button></section>${csrf ? `<form hidden id="csrf-seed"><input name="csrf" value="${e(csrf)}"></form>` : ''}</body></html>`;
}

function seoDescription(description, lang) {
  const tails = lang === 'fr' ? [' Services : conseil énergétique et infrastructures électriques.', ' Découvrez aussi les expertises et secteurs accompagnés.'] : [' Services include energy advisory and power infrastructure.', ' Explore the listed expertise and industries supported.'];
  let result = description || (lang === 'fr' ? 'Africa Power Advisory Holdings accompagne les décisions du secteur de l’énergie.' : 'Africa Power Advisory Holdings supports decisions across the energy sector.');
  for (const tail of tails) { if (result.length >= 140) break; result += tail; }
  if (result.length > 160) result = `${result.slice(0, 157).replace(/\s+\S*$/, '')}…`;
  return result;
}

function renderBody({ lang, route, csrf, recaptchaSiteKey, recaptchaTestMode, query, cmsItems }) {
  const t = locales[lang];
  const isFr = lang === 'fr';
  const contactPath = href(lang, 'contact');
  if (route.errorStatus) {
    const code = route.errorStatus;
    const errorTitle = route.errorTitle;
    return `<section class="error-main"><p class="section-kicker">${code}</p><h1>${e(errorTitle)}</h1><p>${isFr ? 'Le lien a peut-être changé ou la page n’est pas disponible.' : 'The link may have changed or the page is unavailable.'}</p>${code === 404 ? `<form class="search-form" action="${href(lang,'search')}" method="get"><label for="error-search">${e(t.searchLabel)}</label><div><input id="error-search" name="q" type="search" required><button class="button button-dark" type="submit">${e(t.search)}</button></div></form>` : ''}<div class="error-links"><a href="${href(lang,'home')}">${e(t.home)}</a><a href="${href(lang,'services')}">${e(t.nav[2][1])}</a><a href="${href(lang,'actuality')}">${e(t.nav[5][1])}</a><a href="${contactPath}">${e(t.nav[9][1])}</a></div></section>`;
  }
  if (route.key === 'home') return renderHome({ lang, t, cmsItems });

  if (route.key === 'about') return `<section class="page-hero"><p class="eyebrow">Africa Power Advisory Holdings</p><h1>${e(t.nav[1][1])}</h1><p>${isFr ? 'Conseil stratégique et solutions énergétiques pour le secteur de l’électricité.' : 'Strategic advisory and power solutions for the electricity sector.'}</p></section><section class="section prose"><h2>${isFr ? 'Notre rôle' : 'Our role'}</h2><p>${isFr ? 'Africa Power Advisory Holding accompagne les organisations dans l’analyse et l’optimisation du secteur de l’électricité. Les activités décrites comprennent l’assistance technique, économique, financière et environnementale, les études de faisabilité, les audits énergétiques, les projets de production et de réseaux, l’efficacité énergétique, les réseaux intelligents, la transition énergétique et les activités relatives à la réglementation et à l’approvisionnement.' : 'Africa Power Advisory Holding supports organizations in the analysis and optimization of the electricity sector. Stated activities include technical, economic, financial and environmental assistance, feasibility studies, energy audits, generation and network projects, energy efficiency, smart grids, energy transition, regulation and power procurement.'}</p><h2>${isFr ? 'Notre approche' : 'Our approach'}</h2><p>${isFr ? 'La société relie l’analyse technique, économique, financière et environnementale aux décisions concernant l’électricité et les infrastructures énergétiques.' : 'The company connects technical, economic, financial and environmental analysis with decisions about electricity and energy infrastructure.'}</p><a class="button button-dark" href="${href(lang,'services')}">${e(t.nav[2][1])} ↗</a></section>`;

  if (route.key === 'services') return `<section class="page-hero"><p class="eyebrow">${isFr ? 'Expertise sectorielle' : 'Sector expertise'}</p><h1>${e(t.nav[2][1])}</h1><p>${isFr ? 'Services de conseil et secteurs accompagnés.' : 'Advisory services and the industries we support.'}</p></section><section class="section service-hub"><div class="section-heading"><div><div class="section-kicker">${isFr ? 'Explorer par' : 'Browse by'}</div><h2>${isFr ? 'Services et secteurs' : 'Services and industries'}</h2></div><div class="segmented" role="group" aria-label="${isFr ? 'Afficher par services ou secteurs' : 'Show by services or industries'}"><button type="button" data-switch-target="services" aria-pressed="true">${isFr ? 'Services' : 'Services'}</button><button type="button" data-switch-target="industries" aria-pressed="false">${isFr ? 'Secteurs' : 'Industries'}</button></div></div><section id="services"><h2>${isFr ? 'Nos services' : 'Our services'}</h2><div class="service-grid">${services.map((item, i) => `<a class="service-card" href="${serviceHref(lang, item[0])}"><span>0${i + 1}</span><h3>${e(itemName(item, lang))}</h3><p>${e(isFr ? item[4] : item[3])}</p><b aria-hidden="true">↗</b></a>`).join('')}</div></section><section id="industries" class="industry-section"><h2>${isFr ? 'Les secteurs que nous accompagnons' : 'Industries we support'}</h2><div class="industry-grid">${industries.map(item => `<a class="industry-card" href="${industryHref(lang, item[0])}">${e(itemName(item, lang))}<span aria-hidden="true">↗</span></a>`).join('')}</div></section></section>`;

  if (route.key === 'service-detail') {
    const item = services.find(entry => entry[0] === route.slug);
    if (!item) return null;
    const text = isFr ? item[4] : item[3];
    return `<section class="page-hero"><p class="eyebrow">${e(t.nav[2][1])}</p><h1>${e(itemName(item, lang))}</h1><p>${e(text)}</p></section><section class="section prose"><h2>${isFr ? 'Champ d’intervention' : 'Scope'}</h2><p>${e(text)}</p><p>${isFr ? 'Les objectifs et le périmètre de chaque mandat sont établis avec le client.' : 'Objectives and scope for each assignment are agreed with the client.'}</p><a class="button button-dark" href="${contactPath}?topic=${encodeURIComponent(itemName(item, lang))}">${isFr ? 'Discuter d’un mandat' : 'Discuss an engagement'} ↗</a></section>`;
  }
  if (route.key === 'industry-detail') {
    const item = industries.find(entry => entry[0] === route.slug);
    if (!item) return null;
    return `<section class="page-hero"><p class="eyebrow">${e(t.nav[2][1])}</p><h1>${e(itemName(item, lang))}</h1><p>${isFr ? 'Les besoins et les priorités varient selon le contexte de chaque organisation.' : 'Needs and priorities vary with each organization’s context.'}</p></section><section class="section prose"><h2>${isFr ? 'Explorer les services' : 'Explore services'}</h2><p>${isFr ? 'Consultez le catalogue des services pour découvrir les domaines d’intervention publiés.' : 'Visit the services catalogue to explore the published areas of work.'}</p><a class="button button-dark" href="${href(lang,'services')}">${e(t.nav[2][1])} ↗</a></section>`;
  }
  if (route.key === 'experts') return `<section class="page-hero"><p class="eyebrow">${isFr ? 'Équipe' : 'Team'}</p><h1>${e(t.nav[7][1])}</h1><p>${isFr ? 'Les biographies ci-dessous reprennent les informations communiquées par l’entreprise.' : 'The biographies below reflect information supplied by the company.'}</p></section><section class="section experts-grid">${experts.map((person, i) => expertCard(person, lang, i, true)).join('')}</section>`;
  if (route.key === 'expert-detail') {
    const person = experts.find(item => item.slug === route.slug);
    if (!person) return null;
    const portrait = person.imageFile ? `<img class="expert-detail-portrait" src="/assets/team/${e(person.imageFile)}" alt="${e(isFr ? `Portrait de ${person.name}` : `Portrait of ${person.name}`)}" width="420" height="525" fetchpriority="high" decoding="async">` : '';
    return `<nav class="breadcrumbs" aria-label="${isFr ? 'Fil d’Ariane' : 'Breadcrumb'}"><a href="${href(lang,'home')}">${e(t.home)}</a><span aria-hidden="true">›</span><a href="${href(lang,'experts')}">${e(t.nav[7][1])}</a><span aria-hidden="true">›</span><span aria-current="page">${e(person.name)}</span></nav><section class="page-hero"><p class="eyebrow">${isFr ? 'Co-fondateur' : 'Co-founder'}</p><h1>${e(person.name)}</h1><p>${e(isFr ? person.focusFr : person.focusEn)}</p></section><section class="section prose expert-detail-content${person.imageFile ? ' has-portrait' : ''}">${portrait}<div><p>${e(person[lang])}</p><a class="button button-dark" href="${contactPath}">${isFr ? 'Échanger avec l’équipe' : 'Contact the team'} ↗</a></div></section>`;
  }
  if (['actuality-detail','career-detail','project-detail','insight-detail'].includes(route.key)) {
    const type = { 'actuality-detail':'actuality','career-detail':'job','project-detail':'project','insight-detail':'insight' }[route.key];
    const item = cmsItems.find(entry => entry.slug === route.slug && entry.lang === lang && entry.status === 'published' && entry.type === type);
    if (!item) return null;
    const parent = { 'career-detail':'careers','actuality-detail':'actuality','project-detail':'projects','insight-detail':'insights' }[route.key];
    const projectFacts = route.key === 'project-detail' ? `<dl class="project-facts">${[[isFr ? 'Pays' : 'Country',item.country],[isFr ? 'Client' : 'Client',item.clientAuthorized ? item.client : ''],[isFr ? 'Type de projet' : 'Project type',item.projectType],[isFr ? 'Périmètre technique' : 'Technical scope',item.scope],[isFr ? 'Services fournis' : 'Services provided',item.servicesProvided],[isFr ? 'Année' : 'Year',item.projectYear],[isFr ? 'Résultats vérifiés' : 'Verified outcomes',item.outcomeVerified ? item.outcome : '']].filter(([,value]) => value).map(([label,value]) => `<div><dt>${e(label)}</dt><dd>${e(value)}</dd></div>`).join('')}</dl>` : '';
    return `<nav class="breadcrumbs" aria-label="${isFr ? 'Fil d’Ariane' : 'Breadcrumb'}"><a href="${href(lang,'home')}">${e(t.home)}</a><span aria-hidden="true">›</span><a href="${href(lang,parent)}">${e(getTitle(parent,lang))}</a><span aria-hidden="true">›</span><span aria-current="page">${e(item.title)}</span></nav><article class="article-detail"><header class="page-hero"><p class="eyebrow">${route.key === 'career-detail' ? e(isFr ? 'Offre d’emploi' : 'Job opening') : e(item.category || (isFr ? 'Actualité' : 'Company update'))}</p><h1>${e(item.title)}</h1><p>${e(item.summary)}</p><p class="publication-date">${e(new Date(item.publishedAt || item.updatedAt).toLocaleDateString(isFr ? 'fr-CD' : 'en-GB'))}${item.author ? ` · ${e(item.author)}` : ''}</p></header><div class="section prose">${projectFacts}<div>${e(item.body).replace(/\n/g,'<br>')}</div>${route.key === 'career-detail' ? `<a class="button button-dark" href="${href(lang,'careers')}#application">${isFr ? 'Postuler' : 'Apply'} ↗</a>` : `<a class="button button-outline" href="${href(lang,'newsletter')}">${e(t.newsletterCta)}</a>`}</div></article>`;
  }
  if (route.key === 'actuality' && cmsItems.some(item => item.type === 'actuality' && item.lang === lang && item.status === 'published')) {
    const posts = cmsItems.filter(item => item.type === 'actuality' && item.lang === lang && item.status === 'published');
    const category = route.category || ''; const year = route.year || ''; const relatedService = route.relatedService || '';
    const publishedAt = item => Date.parse(item.publishedAt || item.updatedAt || 0) || 0;
    const filtered = posts.filter(item => (!query || `${item.title} ${item.summary} ${item.body}`.toLocaleLowerCase(lang).includes(query.toLocaleLowerCase(lang))) && (!category || item.category === category) && (!year || new Date(publishedAt(item)).getFullYear() === Number(year)) && (!relatedService || item.relatedService === relatedService)).sort((a,b) => publishedAt(b) - publishedAt(a));
    const page = Math.max(1, Number(route.page || 1)); const pageSize = 9; const shown = filtered.slice((page - 1) * pageSize, page * pageSize);
    const categories = [...new Set(posts.map(item => item.category).filter(Boolean))]; const years = [...new Set(posts.map(item => new Date(item.updatedAt).getFullYear()))];
    return `<section class="page-hero"><p class="eyebrow">Africa Power Advisory Holdings</p><h1>${e(getTitle(route.key, lang))}</h1><p>${e(getDescription(route.key, lang))}</p></section><section class="section actuality-content"><form action="${href(lang,'actuality')}" class="filters-form"><label>${isFr ? 'Rechercher' : 'Search'}<input name="q" type="search" value="${e(query)}"></label><label>${isFr ? 'Catégorie' : 'Category'}<select name="category"><option value="">${isFr ? 'Toutes' : 'All'}</option>${categories.map(x => `<option${category === x ? ' selected' : ''}>${e(x)}</option>`).join('')}</select></label><label>${isFr ? 'Année' : 'Year'}<select name="year"><option value="">${isFr ? 'Toutes' : 'All'}</option>${years.map(x => `<option${String(year) === String(x) ? ' selected' : ''}>${x}</option>`).join('')}</select></label><label>${isFr ? 'Service associé' : 'Related service'}<select name="service"><option value="">${isFr ? 'Tous' : 'All'}</option>${services.map(service => `<option value="${e(service[0])}"${relatedService === service[0] ? ' selected' : ''}>${e(itemName(service,lang))}</option>`).join('')}</select></label><button type="submit">${e(t.search)}</button></form><div class="article-grid">${shown.map(post => `<article class="article-card"><p class="eyebrow">${e(post.category || (lang === 'fr' ? 'Annonce' : 'Announcement'))} · ${e(new Date(publishedAt(post)).toLocaleDateString(lang === 'fr' ? 'fr-CD' : 'en-GB'))}</p><h2><a href="${href(lang,'actuality')}${e(post.slug)}/">${e(post.title)}</a></h2><p>${e(post.summary)}</p><a href="${href(lang,'actuality')}${e(post.slug)}/">${isFr ? 'Lire l’actualité' : 'Read update'} →</a></article>`).join('') || `<p>${e(t.searchEmpty)}</p>`}</div>${filtered.length > pageSize ? `<nav class="pagination" aria-label="${isFr ? 'Pagination' : 'Pagination'}"><a href="?page=${page + 1}${query ? `&q=${encodeURIComponent(query)}` : ''}${category ? `&category=${encodeURIComponent(category)}` : ''}${year ? `&year=${encodeURIComponent(year)}` : ''}${relatedService ? `&service=${encodeURIComponent(relatedService)}` : ''}">${isFr ? 'Page suivante' : 'Next page'} →</a></nav>` : ''}<a class="button button-outline" href="${href(lang,'newsletter')}">${e(t.newsletterCta)} →</a></section>`;
  }
  if (route.key === 'careers' && cmsItems.some(item => item.type === 'job' && item.lang === lang && item.status === 'published')) {
    const allJobs = cmsItems.filter(item => item.type === 'job' && item.lang === lang && item.status === 'published');
    const department = route.department || ''; const location = route.location || ''; const contractType = route.contractType || '';
    const jobs = allJobs.filter(job => (!department || job.department === department) && (!location || job.location === location) && (!contractType || job.contractType === contractType) && (!query || `${job.title} ${job.summary} ${job.body}`.toLocaleLowerCase(lang).includes(query.toLocaleLowerCase(lang))));
    const unique = field => [...new Set(allJobs.map(job => job[field]).filter(Boolean))];
    const select = (name, label, values, chosen) => `<label>${label}<select name="${name}"><option value="">${isFr ? 'Tous' : 'All'}</option>${values.map(value => `<option value="${e(value)}"${chosen === value ? ' selected' : ''}>${e(value)}</option>`).join('')}</select></label>`;
    return `<section class="page-hero"><p class="eyebrow">${isFr ? 'Carrières' : 'Careers'}</p><h1>${e(t.nav[8][1])}</h1><p>${e(getDescription(route.key, lang))}</p></section><section class="section careers-content"><form action="${href(lang,'careers')}" method="get" class="filters-form"><label>${isFr ? 'Rechercher' : 'Search'}<input type="search" name="q" value="${e(query)}"></label>${select('department', isFr ? 'Département' : 'Department', unique('department'), department)}${select('location', isFr ? 'Lieu' : 'Location', unique('location'), location)}${select('contract', isFr ? 'Type de contrat' : 'Contract type', unique('contractType'), contractType)}<button type="submit">${isFr ? 'Filtrer les offres' : 'Filter roles'}</button></form><div class="article-grid">${jobs.map(job => `<article class="article-card"><p class="eyebrow">${e([job.department,job.location,job.contractType].filter(Boolean).join(' · '))}</p><h2><a href="${href(lang,'careers')}${e(job.slug)}/">${e(job.title)}</a></h2><p>${e(job.summary)}</p><a href="${href(lang,'careers')}${e(job.slug)}/">${isFr ? 'Voir le poste' : 'View role'} →</a></article>`).join('') || `<p>${e(t.emptyJobs)}</p>`}</div>${renderApplicationForm(lang, csrf, t)}</section>`;
  }
  if (['projects','insights'].includes(route.key)) {
    const type = route.key === 'projects' ? 'project' : 'insight';
    const items = cmsItems.filter(item => item.type === type && item.lang === lang && item.status === 'published');
    if (items.length) return `<section class="page-hero"><p class="eyebrow">Africa Power Advisory Holdings</p><h1>${e(getTitle(route.key,lang))}</h1><p>${e(getDescription(route.key,lang))}</p></section><section class="section article-grid">${items.map(item => `<article class="article-card"><p class="eyebrow">${e(item.category || '')} · ${e(new Date(item.publishedAt || item.updatedAt).toLocaleDateString(isFr ? 'fr-CD' : 'en-GB'))}</p><h2><a href="${href(lang,route.key)}${e(item.slug)}/">${e(item.title)}</a></h2><p>${e(item.summary)}</p></article>`).join('')}</section>`;
  }
  if (route.key === 'actuality' || route.key === 'projects' || route.key === 'insights') {
    const empty = route.key === 'actuality' ? t.emptyNews : route.key === 'projects' ? t.emptyProjects : t.emptyInsights;
    return `<section class="page-hero"><p class="eyebrow">${isFr ? 'Africa Power Advisory Holdings' : 'Africa Power Advisory Holdings'}</p><h1>${e(getTitle(route.key, lang))}</h1><p>${e(getDescription(route.key, lang))}</p></section><section class="section empty-state"><div class="empty-mark" aria-hidden="true">${route.key === 'projects' ? '↗' : route.key === 'insights' ? '⌕' : '◷'}</div><p>${e(empty)}</p>${route.key === 'actuality' ? `<form action="${href(lang, 'actuality')}" method="get" class="filters-form"><label>${isFr ? 'Rechercher les actualités' : 'Search company updates'}<input type="search" name="q" value="${e(query)}"></label><label>${isFr ? 'Catégorie' : 'Category'}<select name="category"><option value="">${isFr ? 'Toutes' : 'All'}</option><option value="announcement">${isFr ? 'Annonces' : 'Announcements'}</option><option value="event">${isFr ? 'Événements' : 'Events'}</option></select></label><button type="submit">${e(t.search)}</button></form>` : ''}</section>`;
  }
  if (route.key === 'careers') return `<section class="page-hero"><p class="eyebrow">${isFr ? 'Carrières' : 'Careers'}</p><h1>${e(t.nav[8][1])}</h1><p>${isFr ? 'Postes publiés et candidatures.' : 'Published positions and applications.'}</p></section><section class="section careers-content"><div class="empty-state"><p>${e(t.emptyJobs)}</p></div><p>${isFr ? 'Les candidatures sont traitées uniquement aux fins d’évaluation d’une candidature, selon l’avis de confidentialité des candidatures.' : 'Applications are processed only to assess an application, as described in the recruitment privacy notice.'} <a href="${href(lang, 'recruitment')}">${isFr ? 'Lire l’avis de confidentialité' : 'Read the recruitment privacy notice'}</a></p>${renderApplicationForm(lang, csrf, t)}</section>`;
  if (route.key === 'contact') return `<section class="page-hero"><p class="eyebrow">${isFr ? 'Nous joindre' : 'Get in touch'}</p><h1>${e(t.contactTitle)}</h1><p>${isFr ? 'Présentez brièvement votre demande.' : 'Tell us briefly about your inquiry.'}</p></section><section class="section contact-content"><div class="contact-info"><h2>${isFr ? 'Parlons de votre projet' : 'Discuss your project'}</h2><p>${e(t.contactNote)}</p><div class="office-list"><h3>${isFr ? 'Nos bureaux' : 'Our offices'}</h3><address><strong>${isFr ? 'Kinshasa' : 'Kinshasa'}</strong><br>${isFr ? 'République démocratique du Congo' : 'Democratic Republic of the Congo'}</address><address><strong>${isFr ? 'Lusaka' : 'Lusaka'}</strong><br>Makeni 55, Kafue Road<br>${isFr ? 'Zambie' : 'Zambia'}</address></div></div>${renderContactForm(lang, csrf, recaptchaSiteKey, recaptchaTestMode, t)}</section>`;
  if (route.key === 'newsletter') return `<section class="page-hero"><p class="eyebrow">${e(t.newsletter)}</p><h1>${e(t.newsletterForm.title)}</h1><p>${e(t.newsletterForm.description)}</p></section><section class="section newsletter-content">${renderNewsletterForm(lang, csrf, t)}</section>`;
  if (route.key === 'search') return renderSearch(lang, query, cmsItems);
  if (route.key === 'sustainability') return `<section class="page-hero"><p class="eyebrow">${isFr ? 'Énergie et avenir' : 'Energy and the future'}</p><h1>${e(t.nav[6][1])}</h1><p>${isFr ? 'Domaines de conseil mentionnés dans les informations fournies par l’entreprise.' : 'Advisory areas listed in information supplied by the company.'}</p></section><section class="section service-grid">${services.filter(i => ['efficacite-energetique', 'transition-energetique', 'systemes-electriques'].includes(i[0])).map(item => `<a class="service-card" href="${serviceHref(lang, item[0])}"><h2>${e(itemName(item, lang))}</h2><p>${e(isFr ? item[4] : item[3])}</p></a>`).join('')}</section>`;
  if (['privacy', 'cookies', 'terms', 'legal', 'accessibility', 'consent', 'recruitment'].includes(route.key)) return renderLegal(lang, route.key, t);
  return null;
}

function renderHome({ lang, t, cmsItems }) {
  const isFr = lang === 'fr'; const contact = href(lang,'contact');
  const published = cmsItems.filter(item => item.type === 'actuality' && item.status === 'published' && item.lang === lang).sort((a,b) => Date.parse(b.publishedAt || b.updatedAt || 0) - Date.parse(a.publishedAt || a.updatedAt || 0)).slice(0,3);
  const publishedInsights = cmsItems.filter(item => item.type === 'insight' && item.status === 'published' && item.lang === lang).slice(0,3);
  const relatedProjects = cmsItems.filter(item => item.type === 'project' && item.status === 'published' && item.lang === lang).slice(0,3);
  const action = (topic, label, primary = false) => `<a class="button ${primary ? 'button-dark' : 'button-outline'}" href="${contact}?topic=${encodeURIComponent(topic)}">${e(label)} ↗</a>`;
  return `<section class="hero hero-home"><div class="hero-content"><p class="eyebrow">${isFr ? 'Conseil stratégique · Énergie · Infrastructures' : 'Strategic advisory · Energy · Infrastructure'}</p><h1>${isFr ? 'L’énergie façonne les choix de demain.' : 'Energy shapes the choices of tomorrow.'}</h1><p class="hero-intro">${isFr ? 'Africa Power Advisory Holdings accompagne les décisions du secteur de l’énergie et de l’électricité.' : 'Africa Power Advisory Holdings supports decision-making across the energy and electricity sector.'}</p><a class="button button-light" href="${contact}?topic=${encodeURIComponent(isFr ? 'Projet' : 'Project')}">${isFr ? 'Parlons de votre projet' : 'Discuss your project'} <span aria-hidden="true">↗</span></a></div><div class="hero-art" aria-hidden="true"><span class="sun"></span><span class="gridline"></span><span class="tower tower-one"></span><span class="tower tower-two"></span></div><span class="hero-note">Africa Power Advisory Holdings</span></section><section class="intro-band"><p>${isFr ? 'Des analyses rigoureuses pour des décisions énergétiques éclairées.' : 'Rigorous analysis for informed energy decisions.'}</p><div class="home-actions" aria-label="${isFr ? 'Demandes de conseil' : 'Advisory requests'}">${action(isFr ? 'Projet' : 'Project', isFr ? 'Discuter d’un projet' : 'Discuss your project', true)}${action(isFr ? 'Conseil énergétique' : 'Energy advisory', isFr ? 'Demander un conseil' : 'Request advisory')}${action(isFr ? 'Expert' : 'Speak with an expert', isFr ? 'Parler à un expert' : 'Speak with an energy expert')}</div></section><section class="section home-intro"><div class="section-kicker">Africa Power Advisory Holdings</div><div class="intro-grid"><h2>${isFr ? 'Conseil stratégique et solutions énergétiques pour l’Afrique.' : 'Strategic energy advisory and power solutions for Africa.'}</h2><p>${isFr ? 'Nous soutenons les décisions liées au secteur de l’électricité, aux infrastructures énergétiques et au développement de projets. Notre approche associe analyse technique, économique et stratégique.' : 'We support decisions related to the electricity sector, energy infrastructure and project development. Our approach combines technical, economic and strategic analysis.'}</p></div></section><section class="section services-preview"><div class="section-heading"><div><div class="section-kicker">${isFr ? 'Nos domaines' : 'Our focus areas'}</div><h2>${isFr ? 'Comprendre. Planifier. Faire avancer.' : 'Understand. Plan. Move forward.'}</h2></div><a class="text-link" href="${href(lang,'services')}">${e(t.nav[2][1])} <span aria-hidden="true">→</span></a></div><div class="service-grid">${services.slice(0,4).map((item,i) => `<a class="service-card" href="${serviceHref(lang,item[0])}"><span>0${i+1}</span><h3>${e(itemName(item,lang))}</h3><p>${e(isFr ? item[4] : item[3])}</p><b aria-hidden="true">↗</b></a>`).join('')}</div><a class="text-link" href="${href(lang,'services')}#industries">${isFr ? 'Explorer les secteurs accompagnés' : 'Explore industries we support'} →</a></section><section class="section intelligence-section"><div class="section-kicker">${isFr ? 'Intelligence énergétique' : 'Energy intelligence'}</div><div class="intelligence-grid"><div><h2>${isFr ? 'Des données pour éclairer les décisions.' : 'Data to inform better decisions.'}</h2><p>${isFr ? 'Domaines d’analyse possibles selon les données vérifiées et le périmètre du mandat.' : 'Potential analysis areas subject to verified data and each engagement’s scope.'}</p><p class="data-note">${isFr ? 'Schéma conceptuel · aucune donnée chiffrée présentée' : 'Conceptual diagram · no numerical data shown'}</p></div><div class="intelligence-visual" role="img" aria-label="${isFr ? 'Schéma conceptuel reliant la demande, la production, les réseaux et les coûts énergétiques.' : 'Conceptual diagram linking demand, generation, networks and energy costs.'}"><span>${isFr ? 'Demande' : 'Demand'}</span><i aria-hidden="true"></i><span>${isFr ? 'Production' : 'Generation'}</span><i aria-hidden="true"></i><span>${isFr ? 'Réseaux' : 'Networks'}</span><i aria-hidden="true"></i><span>${isFr ? 'Coûts' : 'Costs'}</span></div></div></section><section class="section dark-panel"><div><div class="section-kicker">${isFr ? 'Développement de projets' : 'Project development'}</div><h2>${isFr ? 'Études et appui aux infrastructures énergétiques.' : 'Studies and support for energy infrastructure.'}</h2></div><div><p>${isFr ? 'Production, transport, distribution et intégration des énergies renouvelables font partie des domaines d’activité décrits.' : 'Generation, transmission, distribution and renewable integration are among the stated areas of activity.'}</p><a class="button button-light" href="${href(lang,'services')}">${isFr ? 'Voir les services' : 'Explore services'} ↗</a></div></section><section class="section transition-section"><div><div class="section-kicker">${isFr ? 'Transition énergétique' : 'Energy transition'}</div><h2>${isFr ? 'Efficacité, renouvelables, stockage et décarbonation.' : 'Efficiency, renewables, storage and decarbonization.'}</h2></div><p>${isFr ? 'Ces sujets figurent parmi les domaines de conseil communiqués par l’entreprise.' : 'These topics are among the advisory areas stated by the company.'}</p></section>${relatedProjects.length ? `<section class="section featured-projects"><div class="section-heading"><h2>${isFr ? 'Projets sélectionnés' : 'Featured projects'}</h2><a href="${href(lang,'projects')}">${e(t.nav[3][1])} →</a></div>${relatedProjects.map(project => `<article class="article-card"><h3>${e(project.title)}</h3><p>${e(project.summary)}</p></article>`).join('')}</section>` : ''}${publishedInsights.length ? `<section class="section insights-preview"><div class="section-heading"><div><div class="section-kicker">${e(t.nav[4][1])}</div><h2>${isFr ? 'Analyses et publications' : 'Analysis and publications'}</h2></div><a class="text-link" href="${href(lang,'insights')}">${isFr ? 'Toutes les analyses' : 'All insights'} →</a></div><div class="article-grid">${publishedInsights.map(item => `<article class="article-card"><h3><a href="${href(lang,'insights')}${e(item.slug)}/">${e(item.title)}</a></h3><p>${e(item.summary)}</p></article>`).join('')}</div></section>` : ''}<section class="section latest-actuality"><div class="section-heading"><div><div class="section-kicker">${isFr ? 'Actualités' : 'Company updates'}</div><h2>${isFr ? 'À la une' : 'Latest updates'}</h2></div><a class="text-link" href="${href(lang,'actuality')}">${isFr ? 'Toutes les actualités' : 'All updates'} →</a></div>${published.length ? `<div class="article-grid">${published.map(item => `<article class="article-card"><p class="eyebrow">${e(item.category || '')} · ${e(new Date(item.updatedAt).toLocaleDateString(isFr ? 'fr-CD' : 'en-GB'))}</p><h3><a href="${href(lang,'actuality')}${e(item.slug)}/">${e(item.title)}</a></h3><p>${e(item.summary)}</p></article>`).join('')}</div>` : `<p class="empty-inline">${e(t.emptyNews)}</p>`}</section><section class="section home-experts"><div class="section-heading"><div><div class="section-kicker">${isFr ? 'Équipe' : 'Team'}</div><h2>${isFr ? 'Experts en énergie et en politiques publiques.' : 'Experts in energy and public policy.'}</h2></div><a class="text-link" href="${href(lang,'experts')}">${isFr ? 'Rencontrer les experts' : 'Meet the experts'} →</a></div><div class="experts-grid">${experts.map((person,i) => expertCard(person,lang,i)).join('')}</div></section><section class="section careers-teaser"><div><div class="section-kicker">${e(t.nav[8][1])}</div><h2>${isFr ? 'Vous souhaitez travailler dans l’énergie ?' : 'Interested in working in energy?'}</h2><p>${isFr ? 'Aucun poste actuellement publié. Les candidatures spontanées sont ouvertes sous réserve de la disponibilité du formulaire.' : 'No positions are currently published. Spontaneous applications are available subject to form availability.'}</p></div><a class="button button-outline" href="${href(lang,'careers')}">${isFr ? 'Découvrir les carrières' : 'Explore careers'} ↗</a></section><section class="section newsletter-strip"><div><div class="section-kicker">${e(t.newsletter)}</div><h2>${e(t.newsletterForm.title)}</h2><p>${e(t.newsletterForm.description)}</p></div><a class="button button-dark" href="${href(lang,'newsletter')}">${e(t.newsletterCta)} ↗</a></section><section class="section contact-strip"><div><div class="section-kicker">${isFr ? 'Un projet en réflexion ?' : 'Planning a project?'}</div><h2>${isFr ? 'Échangeons sur vos enjeux énergétiques.' : 'Let’s discuss your energy priorities.'}</h2></div><a class="button button-dark" href="${contact}">${isFr ? 'Contacter notre équipe' : 'Contact our team'} ↗</a></section>`;
}

function expertCard(person, lang, index, detailed = false) {
  const isFr = lang === 'fr';
  const initials = person.name.split(/\s+/).map(part => part[0]).slice(0, 2).join('').toUpperCase();
  const portrait = person.file
    ? `<img class="expert-portrait" src="/assets/team/${e(person.imageFile)}" alt="${e(isFr ? `Portrait de ${person.name}` : `Portrait of ${person.name}`)}" width="420" height="525" loading="lazy" decoding="async">`
    : `<div class="expert-portrait expert-monogram" role="img" aria-label="${e(isFr ? `Monogramme de ${person.name}` : `Monogram for ${person.name}`)}">${e(initials)}</div>`;
  return `<article class="expert-card">${portrait}<div class="expert-copy"><span class="expert-index">0${index + 1} · ${isFr ? 'Co-fondateur' : 'Co-founder'}</span><h2>${e(person.name)}</h2><p class="expert-focus">${e(isFr ? person.focusFr : person.focusEn)}</p>${detailed ? `<p>${e(person[lang])}</p>` : ''}<a class="text-link" href="/${lang}/experts/${person.slug}/">${isFr ? 'Lire la biographie' : 'Read bio'} ↗</a></div></article>`;
}

function renderServicesMenu(lang, label, route) {
  const isFr = lang === 'fr';
  const servicesHeading = isFr ? 'Services' : 'Services';
  const industriesHeading = isFr ? 'Secteurs' : 'Industries';
  const detailLinks = services.map(item => `<a href="${serviceHref(lang,item[0])}">${e(itemName(item,lang))}</a>`).join('');
  const sectorLinks = industries.map(item => `<a href="${industryHref(lang,item[0])}">${e(itemName(item,lang))}</a>`).join('');
  return `<details class="nav-dropdown"${['services','service-detail','industry-detail'].includes(route.key) ? ' data-active="true"' : ''}><summary>${e(label)}</summary><div class="nav-dropdown-panel"><a class="nav-hub-link" href="${href(lang,'services')}"${route.key === 'services' ? ' aria-current="page"' : ''}>${isFr ? 'Voir tous les services et secteurs' : 'View all services and industries'} ↗</a><div class="nav-dropdown-columns"><section><h2>${servicesHeading}</h2>${detailLinks}</section><section><h2>${industriesHeading}</h2>${sectorLinks}</section></div></div></details>`;
}

function renderContactForm(lang, csrf, recaptchaSiteKey, recaptchaTestMode, t) {
  const f = t.form;
  return `<form class="site-form" method="post" action="/api/contact?lang=${lang}" data-async-form data-form-type="contact" novalidate><input type="hidden" name="csrf" value="${e(csrf)}"><div class="form-error-summary" data-error-summary tabindex="-1" hidden></div><div class="form-grid"><label>${e(f.name)} *<input name="name" autocomplete="name" required maxlength="120"><span class="field-error" data-error-for="name"></span></label><label>${e(f.email)} *<input name="email" type="email" autocomplete="email" required maxlength="254"><span class="field-error" data-error-for="email"></span></label><label>${e(f.phone)}<input name="phone" type="tel" autocomplete="tel" maxlength="40"></label><label>${e(f.organization)}<input name="organization" autocomplete="organization" maxlength="120"></label><label>${e(f.topic)} *<select name="topic" required><option value="">${isLangFr(lang) ? 'Choisir un objet' : 'Choose a subject'}</option>${[...(isLangFr(lang) ? ['Demande générale', 'Conseil énergétique', 'Projet', 'Expert'] : ['General inquiry', 'Energy advisory', 'Project', 'Speak with an expert']), ...services.map(item => itemName(item, lang))].map(x => `<option>${e(x)}</option>`).join('')}</select><span class="field-error" data-error-for="topic"></span></label><label class="form-span">${e(f.message)} *<textarea name="message" rows="6" required maxlength="5000"></textarea><span class="field-error" data-error-for="message"></span></label></div><p class="form-note">${e(t.contactNote)} <a href="${href(lang, 'privacy')}">${isLangFr(lang) ? 'Politique de confidentialité' : 'Privacy policy'}</a></p><label class="checkbox-label"><input type="checkbox" name="privacy" value="yes" required><span>${e(f.privacy)} *</span></label><span class="field-error" data-error-for="privacy"></span><div class="captcha-consent"><label class="checkbox-label"><input type="checkbox" name="captchaConsent" value="yes" data-load-captcha required><span>${e(t.captchaLoad)}. ${e(t.captchaConsent)} *</span></label><div class="recaptcha-slot" data-recaptcha data-sitekey="${e(recaptchaSiteKey)}" data-test-mode="${recaptchaTestMode}" data-label="${e(t.captcha)}"></div></div><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><button class="button button-dark" type="submit">${e(f.send)}</button><p class="form-status" data-form-status role="status" aria-live="polite" tabindex="-1"></p></form>`;
}

function renderNewsletterForm(lang, csrf, t) {
  const f = t.newsletterForm;
  return `<form class="site-form narrow-form" method="post" action="/api/newsletter?lang=${lang}" data-async-form data-form-type="newsletter" novalidate><input type="hidden" name="csrf" value="${e(csrf)}"><div class="form-error-summary" data-error-summary tabindex="-1" hidden></div><label>${isLangFr(lang) ? 'Adresse courriel' : 'Email address'} *<input name="email" type="email" autocomplete="email" required maxlength="254"><span class="field-error" data-error-for="email"></span></label><input type="hidden" name="lang" value="${lang}"><label class="checkbox-label"><input type="checkbox" name="consent" value="yes" required><span>${e(f.consent)} *</span></label><span class="field-error" data-error-for="consent"></span><p class="form-note">${e(f.description)} <a href="${href(lang, 'privacy')}">${isLangFr(lang) ? 'Politique de confidentialité' : 'Privacy policy'}</a></p><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><button class="button button-dark" type="submit">${e(f.submit)}</button><p class="form-status" data-form-status role="status" aria-live="polite" tabindex="-1"></p></form>`;
}

function renderApplicationForm(lang, csrf, t) {
  const f = t.careersForm;
  return `<form id="application" class="site-form application-form" method="post" action="/api/application?lang=${lang}" enctype="multipart/form-data" data-async-form data-form-type="application" novalidate><input type="hidden" name="csrf" value="${e(csrf)}"><div class="form-error-summary" data-error-summary tabindex="-1" hidden></div><h2>${e(f.title)}</h2><div class="form-grid"><label>${e(f.name)} *<input name="name" autocomplete="name" required maxlength="120"><span class="field-error" data-error-for="name"></span></label><label>${e(f.email)} *<input name="email" type="email" autocomplete="email" required maxlength="254"><span class="field-error" data-error-for="email"></span></label><label>${e(f.phone)}<input name="phone" autocomplete="tel" maxlength="40"></label><label>${e(f.role)} *<input name="role" required maxlength="120"><span class="field-error" data-error-for="role"></span></label><label class="form-span">${e(f.cv)} *<input type="file" name="cv" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required><span class="field-error" data-error-for="cv"></span></label></div><label class="checkbox-label"><input type="checkbox" name="privacy" value="yes" required><span>${e(f.privacy)} *</span></label><span class="field-error" data-error-for="privacy"></span><label class="checkbox-label"><input type="checkbox" name="futureConsent" value="yes"><span>${e(f.future)}</span></label><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><p class="form-note"><a href="${href(lang, 'recruitment')}">${isLangFr(lang) ? 'Avis de confidentialité des candidatures' : 'Recruitment privacy notice'}</a></p><button class="button button-dark" type="submit">${e(f.submit)}</button><p class="form-status" data-form-status role="status" aria-live="polite" tabindex="-1"></p></form>`;
}

function renderSearch(lang, query, cmsItems = []) {
  const isFr = lang === 'fr';
  const t = locales[lang];
  const items = [
    ...services.map(item => ({ title: itemName(item, lang), summary: isFr ? item[4] : item[3], url: serviceHref(lang, item[0]) })),
    ...industries.map(item => ({ title: itemName(item, lang), summary: isFr ? 'Secteur accompagné par l’entreprise.' : 'Industry listed by the company.', url: industryHref(lang, item[0]) })),
    ...experts.map(p => ({ title: p.name, summary: p[lang], url: `/${lang}/experts/${p.slug}/` })),
    ...Object.entries(t.nav).map(([, row]) => ({ title: row[1], summary: '', url: href(lang, row[0]) })),
    ...Object.keys(routePages).filter(key => key !== 'search').map(key => {
      const page = renderBody({ lang, route: { key }, csrf: '', recaptchaSiteKey: '', recaptchaTestMode: false, query: '', cmsItems });
      const summary = String(page || '').replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, ' ').replace(/&#39;/g, "'").replace(/\s+/g, ' ').trim();
      return { title: getTitle(key, lang), summary, url: href(lang, key) };
    }),
    ...cmsItems.filter(item => item.lang === lang && item.status === 'published').map(item => { const parent = { job:'careers', actuality:'actuality', project:'projects', insight:'insights' }[item.type] || 'actuality'; return { title: item.title, summary: `${item.summary} ${item.body || ''} ${item.country || ''} ${item.projectType || ''} ${item.scope || ''} ${item.servicesProvided || ''} ${item.outcomeVerified ? item.outcome || '' : ''}`, url: `${href(lang,parent)}${item.slug}/` }; }),
  ];
  const q = query.trim().toLocaleLowerCase(lang);
  const results = q ? items.filter(item => `${item.title} ${item.summary}`.toLocaleLowerCase(lang).includes(q)) : [];
  return `<section class="page-hero"><p class="eyebrow">${e(t.search)}</p><h1>${e(t.searchResults)}</h1><form class="filters-form search-page-form" action="${href(lang, 'search')}" method="get"><label>${e(t.searchLabel)}<input name="q" type="search" required value="${e(query)}" placeholder="${e(t.searchPlaceholder)}"></label><button type="submit">${e(t.search)}</button></form></section><section class="section search-results" aria-live="polite">${results.length ? `<p>${results.length} ${isFr ? 'résultat(s)' : 'result(s)'}</p>${results.map(item => `<article class="search-result"><h2><a href="${item.url}">${e(item.title)}</a></h2><p>${e(item.summary)}</p></article>`).join('')}` : `<p>${e(t.searchEmpty)}</p>`}</section>`;
}

function renderLegal(lang, key, t) {
  const isFr = lang === 'fr';
  const sections = {
    privacy: isFr ? [['Données de contact', 'Les demandes envoyées par le formulaire peuvent inclure le nom, l’adresse courriel, l’objet et le message. Le téléphone et l’organisation sont facultatifs.'], ['Candidatures', 'Les candidatures incluent le nom, l’adresse courriel, le domaine visé et un CV. Le téléphone et la conservation pour d’autres possibilités sont facultatifs. Le CV est stocké hors du répertoire public et accessible aux personnes habilitées.'], ['Infolettre', 'L’adresse courriel n’est inscrite qu’après confirmation du lien d’adhésion. Chaque envoi doit permettre de se désabonner.'], ['Témoins et services tiers', 'Le thème et certaines préférences fonctionnelles sont stockés localement. reCAPTCHA n’est chargé qu’après action explicite dans le formulaire de contact.'], ['Demandes et durée de conservation', 'Les règles de conservation, les coordonnées du responsable de la confidentialité et les modalités d’exercice des droits doivent être fixées avec l’entreprise avant la mise en service.']] : [['Contact data', 'Contact inquiries may include name, email address, subject and message. Phone and organization are optional.'], ['Applications', 'Applications include name, email address, area of interest and a CV. Phone and consent to retention for other opportunities are optional. CV files are stored outside the public directory and restricted to authorized people.'], ['Newsletter', 'An email address is subscribed only after confirmation through the opt-in link. Every message must provide an unsubscribe mechanism.'], ['Cookies and third parties', 'Theme and functional preferences are stored locally. reCAPTCHA loads only after an explicit action in the contact form.'], ['Requests and retention', 'Retention periods, privacy contact details and processes for rights requests must be established with the company before launch.']],
    cookies: isFr ? [['Stockage nécessaire', 'Le site utilise un cookie de sécurité temporaire pour valider les formulaires. Le choix du thème peut être conservé dans le stockage local du navigateur.'], ['Services facultatifs', 'Google reCAPTCHA ne se charge que lorsque la personne le demande dans le formulaire de contact. Ce service peut recevoir des données techniques. Les détails doivent être confirmés dans le registre des tiers et lors de la revue juridique.'], ['Préférences', 'Vous pouvez effacer les préférences locales dans les réglages de votre navigateur ou gérer le chargement des services facultatifs depuis cette page.']] : [['Necessary storage', 'The site uses a temporary security cookie to validate forms. Theme choice may be kept in browser local storage.'], ['Optional services', 'Google reCAPTCHA loads only when requested in the contact form. The service may receive technical data. Details require confirmation in the third-party register and legal review.'], ['Preferences', 'You can clear local preferences in your browser settings or manage optional services from this page.']],
    terms: isFr ? [['Utilisation', 'Le contenu du site présente les services et domaines décrits dans les informations fournies par l’entreprise. Toute mission professionnelle fait l’objet d’un accord distinct.'], ['Exactitude', 'Les projets, clients, résultats, tarifs et engagements particuliers ne sont affichés que lorsqu’ils sont vérifiés et approuvés.'], ['Revue juridique', t.legalReview]] : [['Use', 'This site presents services and areas described in information supplied by the company. Professional engagements are governed by separate agreements.'], ['Accuracy', 'Projects, clients, outcomes, fees and specific commitments are displayed only when verified and approved.'], ['Legal review', t.legalReview]],
    legal: isFr ? [['Éditeur', 'Africa Power Advisory Holding, société à responsabilité limitée (SARL), établie à Kinshasa, République démocratique du Congo. Marque utilisée : Africa Power Advisory Holdings.'], ['Revue juridique', t.legalReview]] : [['Publisher', 'Africa Power Advisory Holding, a limited liability company (SARL), based in Kinshasa, Democratic Republic of the Congo. Brand used: Africa Power Advisory Holdings.'], ['Legal review', t.legalReview]],
    accessibility: isFr ? [['Approche', 'Le site est conçu pour fonctionner avec le clavier, les lecteurs d’écran, l’agrandissement du texte et les préférences de mouvement réduit.'], ['Signaler un problème', 'Les coordonnées de contact accessibles seront publiées lorsque l’entreprise les aura confirmées.'], ['État des vérifications', 'La déclaration doit être complétée par les vérifications WCAG 2.2 AA et la revue de personnes utilisatrices avant lancement.']] : [['Approach', 'The site is designed for keyboard access, screen readers, text enlargement and reduced-motion preferences.'], ['Report an issue', 'Accessible contact details will be published once confirmed by the company.'], ['Review status', 'Complete WCAG 2.2 AA checks and review with users before launch.']],
    consent: isFr ? [['Préférences', 'Les fonctions de base ne requièrent pas de services publicitaires ou d’analyse. Le thème est une préférence locale.'], ['reCAPTCHA', 'Vous pouvez charger Google reCAPTCHA au moment de soumettre une demande de contact; ce service est désactivé jusque-là.'], ['Infolettre', 'Le consentement à l’infolettre est séparé et confirmé par courriel. Pour vous désabonner, utilisez le lien dans chaque courriel.']] : [['Preferences', 'Core site functions do not require advertising or analytics services. Theme is a local preference.'], ['reCAPTCHA', 'You can load Google reCAPTCHA when submitting a contact inquiry; it remains off until then.'], ['Newsletter', 'Newsletter consent is separate and confirmed by email. Use the link in any newsletter to unsubscribe.']],
    recruitment: isFr ? [['Données recueillies', 'Nom, courriel, domaine visé et CV; numéro de téléphone facultatif. Le consentement facultatif à la conservation pour de futures possibilités est distinct.'], ['Utilisation et accès', 'Les informations servent à traiter la candidature et ne sont accessibles qu’aux personnes chargées du recrutement. Les fichiers sont conservés en stockage privé, jamais accessibles par un lien public.'], ['Conservation et demandes', 'La durée de conservation, le contact de confidentialité et les modalités de suppression doivent être approuvés par l’entreprise et un conseiller juridique avant toute réception de candidatures en production.']] : [['Data collected', 'Name, email, area of interest and CV; phone is optional. Optional consent to retain the application for future opportunities is separate.'], ['Use and access', 'Information is used to process the application and is available only to authorized recruitment personnel. Files are held in private storage and are never exposed through a public URL.'], ['Retention and requests', 'The retention period, privacy contact and deletion process must be approved by the company and counsel before production applications are accepted.']],
  };
  const body = sections[key] || [];
  return `<section class="page-hero"><p class="eyebrow">${isFr ? 'Informations' : 'Information'}</p><h1>${e(getTitle(key, lang))}</h1><p>${e(getDescription(key, lang))}</p></section><section class="section prose legal-content">${body.map(([heading, copy]) => `<section><h2>${e(heading)}</h2><p>${e(copy)}</p></section>`).join('')}${key === 'consent' ? `<button class="button button-outline" type="button" data-clear-preferences>${isFr ? 'Effacer mes préférences locales' : 'Clear my local preferences'}</button>` : ''}</section>`;
}

function isLangFr(lang) { return lang === 'fr'; }

export { href as localizedHref, serviceHref, industryHref, getTitle, getDescription };
